def infer(a,b):
    m={}
    for i,s in enumerate(a):
        if s in b: m[i]=b.index(s)
    return m
def apply(m,fig,new=None):
    out=[None]*len(fig)
    for i,j in m.items(): out[j]=fig[i]
    for k in range(len(out)):
        if out[k] is None: out[k]=new
    return out

f=[["up","+","$","D","tri"],["D","tri","up","$","+"],["$","+","D","up","tri"],["up","tri","$","D","+"]]
m=infer(f[0],f[1])
assert infer(f[1],f[2])==m and infer(f[2],f[3])==m
ans=apply(m,f[3])
opts={"A":["$","tri","D","up","+"],"B":["D","+","up","$","tri"],"C":["$","tri","D","+","up"],"D":["D","$","up","+","tri"]}
assert ans==opts["B"]
for k in "ACD": assert ans!=opts[k]
